create extension if not exists pgcrypto;
create table if not exists public.nexaro_edit_sources (
 id uuid primary key default gen_random_uuid(), app_name text not null, category text not null,
 source_type text not null check (source_type in ('official','store','apk_catalog','tutorial','community','security')),
 title text not null, url text not null check (url ~ '^https://'), description text not null default '',
 is_official boolean not null default false,
 verification_status text not null default 'unverified' check (verification_status in ('unverified','listed_by_publisher','reviewed','flagged')),
 last_reviewed_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 unique(app_name,title,url)
);
create index if not exists nexaro_edit_sources_app_name_idx on public.nexaro_edit_sources(lower(app_name));
create index if not exists nexaro_edit_sources_source_type_idx on public.nexaro_edit_sources(source_type);
alter table public.nexaro_edit_sources enable row level security;
drop policy if exists "Public can read Nexaro Edit Hub sources" on public.nexaro_edit_sources;
create policy "Public can read Nexaro Edit Hub sources" on public.nexaro_edit_sources for select to anon, authenticated using (true);
grant select on public.nexaro_edit_sources to anon, authenticated;
create table if not exists public.nexaro_edit_search_events (id uuid primary key default gen_random_uuid(), query_length integer not null check(query_length between 1 and 500), result_count integer not null default 0 check(result_count>=0), created_at timestamptz not null default now());
alter table public.nexaro_edit_search_events enable row level security;
